"use strict";
// Completionist menu. Static quest data comes from data.js (generated by tools/build/build-mod.ts);
// statuses and the player's location come from Completionist:MenuBridge through OSF UI state.

(function () {
  const DATA = window.COMPLETIONIST_DATA;
  const bridge = window.osfui;
  const demo = !bridge; // previewing in a browser: fake progress so the layout can be checked

  const NOT_STARTED = 0, IN_PROGRESS = 1, COMPLETED = 2, FAILED = 3, LOCKED_OUT = 4;
  const isDone = (s) => s === COMPLETED || s === LOCKED_OUT; // locked out = the other branch of an either/or choice was completed
  const isFinished = (s) => isDone(s) || s === FAILED; // nothing left to do
  const TABS = [
    { id: "log", label: "LOG" },
    { id: "here", label: "HERE" },
    { id: "locations", label: "LOCATIONS" },
    { id: "questlines", label: "QUESTS" },
    { id: "activities", label: "ACTIVITIES" },
  ];
  const SORTS = [
    { id: "default", label: "DEFAULT" },
    { id: "name", label: "NAME" },
    { id: "status", label: "STATUS" },
    { id: "type", label: "TYPE" },
    { id: "place", label: "LOCATION" },
  ];
  const FILTERS = [
    { id: "all", label: "ALL", test: () => true },
    { id: "missing", label: "NOT STARTED", test: (s) => s === NOT_STARTED },
    { id: "active", label: "IN PROGRESS", test: (s) => s === IN_PROGRESS },
    { id: "done", label: "COMPLETED", test: isDone },
  ];
  const FACTION_TAGS = {
    constellation: "CONSTELLATION", "united-colonies": "UC VANGUARD", "freestar-collective": "FREESTAR",
    "ryujin-industries": "RYUJIN", "crimson-fleet": "CRIMSON FLEET", "house-varuun": "HOUSE VA'RUUN",
    "terran-armada": "TERRAN ARMADA", "trackers-alliance": "TRACKERS",
  };
  const TYPE_NOUNS = { main: "main mission", faction: "faction mission", side: "side mission", companion: "companion mission", activity: "activity" };

  const view = {
    tab: "here",
    selected: { log: "active", here: "all", locations: null, questlines: null, activities: "all" },
    filter: "all",
    spoilers: readSetting("spoilers", false), // true = hide names of quests you haven't started
    sort: readSetting("sort", "default"), // see SORTS (checked below)
    focus: "list", // "side" (place / questline / category list), "list" (quests) or "cards" (nothing-tracked page)
    row: 0, // selected quest row when focus is "list"
    card: 0, // selected card when focus is "cards"
    input: "keyboard", // "gamepad" after a controller button, so prompts show controller buttons
  };
  if (!SORTS.some((s) => s.id === view.sort)) view.sort = "default";
  let shownQuests = []; // quests in the detail list, in display order (for selection and actions)
  let shownCards = []; // systems on the nothing-tracked page
  let hereLayout = "city"; // Here tab: "city", "places" (planet or system) or "nowhere"
  let tracked = new Set(); // ids of quests the player is tracking (the game's "active" quests)
  let inSpace = false;
  let survey = -1; // current planet's survey progress, 0-1 (-1 = no planet)
  let statuses = new Map(); // quest id -> status; quests missing here aren't in the player's load order
  let locationChain = []; // FormIDs, most specific first
  let loaded = demo; // true once Papyrus has published statuses
  let manual = new Set(); // quest ids with a manual override (status values arrive +10)
  let unityEntered = false; // NG+-only quests count once the player has entered Unity
  let gameActivities = null; // the game's own "Activities Completed" stat
  const demoAuto = new Map(); // preview only: detected status to restore on "reset to auto"

  const questsById = new Map(DATA.quests.map((q) => [q.id, q]));

  // ------------------------------------------------------------------ state from Papyrus

  function readSetting(key, fallback) {
    try {
      const value = localStorage.getItem("completionist." + key);
      return value === null ? fallback : JSON.parse(value);
    } catch (e) {
      return fallback;
    }
  }
  function writeSetting(key, value) {
    try { localStorage.setItem("completionist." + key, JSON.stringify(value)); } catch (e) { /* storage unavailable */ }
  }

  let renderQueued = false;
  function queueRender() {
    if (renderQueued) return;
    renderQueued = true;
    // A timer, not requestAnimationFrame: the game's browser pauses animation frames until the
    // menu gets focus, so the first progress update would wait for a mouse click.
    setTimeout(() => { renderQueued = false; render(); }, 0);
  }

  function ingestStatuses() {
    const pages = bridge.state.get("pages") || 0;
    const next = new Map();
    const nextManual = new Set();
    for (let p = 0; p < pages; p++) {
      const ids = bridge.state.get("ids" + p) || [];
      const values = bridge.state.get("status" + p) || [];
      // Papyrus strings are case-insensitive and shared engine-wide, so "ri01" can arrive as
      // "RI01" (the editor ID the game already holds). Our ids are lowercase.
      ids.forEach((id, i) => {
        const key = String(id).toLowerCase();
        const raw = values[i] ?? NOT_STARTED;
        next.set(key, raw % 10);
        if (raw >= 10) nextManual.add(key);
      });
    }
    statuses = next;
    manual = nextManual;
    loaded = pages > 0;
    queueRender();
  }

  if (demo) {
    let seed = 11;
    const rand = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
    DATA.quests.forEach((q) => {
      const r = rand();
      statuses.set(q.id, r < 0.38 ? COMPLETED : r < 0.48 ? IN_PROGRESS : r < 0.5 ? FAILED : NOT_STARTED);
    });
    // Preview only: ?here=<place name> (or "none") fakes the player's location, &space=1 "in space",
    // &survey=0.63 a planet's survey progress.
    const params = new URLSearchParams(location.search);
    const hereName = params.get("here") || "Neon";
    const herePlaceData = Object.values(DATA.places).find((p) => p.name === hereName && p.loc);
    locationChain = herePlaceData ? [runtimeIdFor(herePlaceData.loc)] : [];
    inSpace = params.get("space") === "1";
    survey = params.has("survey") ? Number(params.get("survey")) : -1;
  } else {
    bridge.state.on("pages", ingestStatuses);
    for (let p = 0; p < 8; p++) {
      bridge.state.on("ids" + p, ingestStatuses);
      bridge.state.on("status" + p, ingestStatuses);
    }
    bridge.state.on("unityEntered", (value) => { unityEntered = value === true; queueRender(); });
    bridge.state.on("gameActivities", (value) => { gameActivities = typeof value === "number" ? value : null; queueRender(); });
    bridge.state.on("tracked", (ids) => {
      tracked = new Set((Array.isArray(ids) ? ids : []).map((id) => String(id).toLowerCase()));
      queueRender();
    });
    bridge.on("tracked", (event) => {
      const [rawId, active, wanted] = (event && event.args) || [];
      const id = String(rawId).toLowerCase();
      const q = questsById.get(id);
      if (active) tracked.add(id); else tracked.delete(id);
      queueRender();
      if (!q) return;
      if (wanted === false) showToast(active ? "Couldn't stop tracking " + q.name : "Stopped tracking: " + q.name);
      else showToast(active ? "Now tracking: " + q.name : "Couldn't track " + q.name + ". The game didn't accept it.");
    });
    bridge.state.on("inSpace", (value) => { inSpace = value === true; queueRender(); });
    bridge.state.on("survey", (value) => { survey = typeof value === "number" ? value : -1; queueRender(); });
    bridge.state.on("location", (ids) => { locationChain = Array.isArray(ids) ? ids : []; queueRender(); });
  }

  // ------------------------------------------------------------------ places

  // Runtime FormIDs carry the load-order index of their plugin, which the static data can't know.
  // Starfield.esm is always index 00; full masters match on the low 24 bits, medium masters
  // (0xFD prefix) on 16 and small masters (0xFE prefix) on 12.
  function matchesLocation(runtimeId, locKey) {
    if (!locKey) return false;
    const [plugin, hex] = locKey.split("|");
    const local = parseInt(hex, 16);
    const id = runtimeId >>> 0;
    if (plugin.toLowerCase() === "starfield.esm") return id === local;
    const top = id >>> 24;
    if (top === 0xfe) return (id & 0xfff) === (local & 0xfff);
    if (top === 0xfd) return (id & 0xffff) === (local & 0xffff);
    return (id & 0xffffff) === local;
  }
  function runtimeIdFor(locKey) {
    return parseInt(locKey.split("|")[1], 16);
  }

  function placeChain(placeKey) {
    const chain = [];
    for (let key = placeKey; key && DATA.places[key] && chain.length < 8; key = DATA.places[key].parent) {
      chain.push({ key, ...DATA.places[key] });
    }
    return chain;
  }

  // The most specific tracked place containing the player.
  function herePlace() {
    for (const runtimeId of locationChain) {
      for (const [key, place] of Object.entries(DATA.places)) {
        if (matchesLocation(runtimeId, place.loc)) return key;
      }
    }
    return null;
  }

  // ------------------------------------------------------------------ data helpers

  const available = (q) => demo || statuses.has(q.id);
  const statusOf = (q) => statuses.get(q.id) ?? NOT_STARTED;

  // NG+-only quests (Among the Stars, Foreknowledge) can't be done before entering Unity.
  const notYetAvailable = (q) => q.ngPlusOnly && !unityEntered;

  function tally(quests) {
    const t = { total: 0, done: 0, active: 0, failed: 0 };
    for (const q of quests) {
      if (!available(q) || notYetAvailable(q)) continue;
      t.total++;
      const s = statusOf(q);
      if (isDone(s)) t.done++;
      else if (s === IN_PROGRESS) t.active++;
      else if (s === FAILED) t.failed++;
    }
    t.missing = t.total - t.done - t.active - t.failed;
    return t;
  }

  // Quests whose start place is key or lies under it.
  function questsUnder(key) {
    return DATA.quests.filter((q) => placeChain(q.place).some((p) => p.key === key));
  }

  // Location tree: systems (by size) > planets > selectable places that hold quests directly.
  function locationRows(onlyActivities) {
    const pool = DATA.quests.filter((q) => available(q) && (!onlyActivities || q.activity));
    const systems = new Map();
    const anywhere = [];
    for (const q of pool) {
      const chain = placeChain(q.place);
      const system = chain.find((p) => p.kind === "system");
      if (!system) { anywhere.push(q); continue; }
      if (!systems.has(system.key)) systems.set(system.key, { place: system, quests: [], planets: new Map() });
      const s = systems.get(system.key);
      s.quests.push(q);
      const planet = chain.find((p) => p.kind === "planet");
      const planetKey = planet ? planet.key : system.key;
      if (!s.planets.has(planetKey)) s.planets.set(planetKey, { place: planet || system, holders: new Map() });
      const holder = chain[0];
      const holders = s.planets.get(planetKey).holders;
      if (!holders.has(holder.key)) holders.set(holder.key, { place: holder, quests: [] });
      holders.get(holder.key).quests.push(q);
    }

    const rows = [];
    const byTotal = (a, b) => b.quests.length - a.quests.length || a.place.name.localeCompare(b.place.name);
    for (const s of [...systems.values()].sort(byTotal)) {
      const t = tally(s.quests);
      rows.push({ kind: "group", label: s.place.name.toUpperCase(), frac: t.done + " / " + t.total });
      const planetSize = (planet) => [...planet.holders.values()].reduce((n, h) => n + h.quests.length, 0);
      for (const planet of [...s.planets.values()].sort((a, b) => planetSize(b) - planetSize(a))) {
        if (planet.place.kind === "planet") rows.push({ kind: "subgroup", label: planet.place.name });
        for (const holder of [...planet.holders.values()].sort(byTotal)) {
          rows.push({ kind: "item", key: holder.place.key, label: holder.place.name, quests: holder.quests });
        }
      }
    }
    if (anywhere.length) {
      const t = tally(anywhere);
      rows.push({ kind: "group", label: "ANYWHERE", frac: t.done + " / " + t.total });
      rows.push({ kind: "item", key: "anywhere", label: "Encounters and events", quests: anywhere });
    }
    return rows;
  }

  function questlineRows() {
    return DATA.questlines
      .map((line) => ({ kind: "item", key: line.id, label: line.name, sub: line.group, quests: line.quests.map((id) => questsById.get(id)).filter((q) => q && available(q)) }))
      .filter((row) => row.quests.length > 0);
  }

  function activityRows() {
    const all = DATA.quests.filter((q) => q.activity && available(q));
    return [{ kind: "item", key: "all", label: "All activities", quests: all }, ...locationRows(true)];
  }

  // Log: only quests the player has found (started, finished or failed), like the game's Missions menu.
  function logRows() {
    const found = DATA.quests.filter((q) => available(q) && [IN_PROGRESS, COMPLETED, FAILED].includes(statusOf(q)));
    const kindOf = (q) => (q.activity ? 3 : q.type === "main" ? 0 : q.type === "faction" ? 1 : 2);
    const active = found.filter((q) => statusOf(q) === IN_PROGRESS).sort((a, b) => kindOf(a) - kindOf(b));
    const ofKind = (k) => active.filter((q) => kindOf(q) === k);
    const item = (key, label, quests, sub) => ({ kind: "item", key, label, quests, count: true, sub });
    return [
      { kind: "group", label: "FOUND SO FAR", frac: String(found.length) },
      item("active", "In progress", active),
      item("main", "Main", ofKind(0), true),
      item("faction", "Faction", ofKind(1), true),
      item("side", "Side", ofKind(2), true),
      item("activity", "Activities", ofKind(3), true),
      item("completed", "Completed", found.filter((q) => statusOf(q) === COMPLETED)),
      item("failed", "Failed", found.filter((q) => statusOf(q) === FAILED)),
    ];
  }

  // Here on a planet or in a system: the whole place, then each place in it (hubs or planets).
  function hereRows() {
    const key = herePlace();
    const place = key && DATA.places[key];
    if (!place || (place.kind !== "planet" && place.kind !== "system")) return [];
    const level = place.kind === "planet" ? "hub" : "planet";
    return [
      { kind: "group", label: (level === "hub" ? "PLACES ON " : "PLANETS AND MOONS IN ") + place.name.toUpperCase() },
      { kind: "item", key: "all", label: "All of " + place.name, quests: questsUnder(key) },
      ...placeCards(key, level).map((c) => ({ kind: "item", key: c.key, label: c.label, quests: c.quests, loc: c.loc })),
    ];
  }

  function sideRows() {
    if (view.tab === "log") return logRows();
    if (view.tab === "here") return hereRows();
    if (view.tab === "locations") return locationRows(false);
    if (view.tab === "questlines") return questlineRows();
    if (view.tab === "activities") return activityRows();
    return [];
  }

  // ------------------------------------------------------------------ rendering

  const el = (tag, attrs, ...children) => {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v === undefined || v === null || v === false) continue;
      if (k === "class") node.className = v;
      else if (k === "text") node.textContent = v;
      else if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v === true ? "" : v);
    }
    for (const child of children.flat()) if (child) node.append(child);
    return node;
  };

  const SVG = "http://www.w3.org/2000/svg";
  function statusIcon(status, onLight) {
    const svg = document.createElementNS(SVG, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("viewBox", "0 0 18 18");
    svg.setAttribute("aria-hidden", "true");
    const stroke = onLight ? "#0b0f14" : status === IN_PROGRESS ? "#ee8a2a" : status === FAILED ? "#d64a2c" : status === COMPLETED ? "#e9edf1" : "#8d99a6";
    const add = (name, attrs) => {
      const node = document.createElementNS(SVG, name);
      for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
      svg.append(node);
    };
    add("rect", { x: 1.5, y: 1.5, width: 15, height: 15, fill: status === COMPLETED ? stroke : "none", stroke, "stroke-width": 1.5 });
    if (status === COMPLETED) add("path", { d: "M5 9.5l2.6 2.6L13 6.5", fill: "none", stroke: onLight ? "#e9edf1" : "#0b0f14", "stroke-width": 2 });
    if (status === IN_PROGRESS) add("rect", { x: 6, y: 6, width: 6, height: 6, fill: stroke });
    if (status === FAILED) add("path", { d: "M5.5 5.5l7 7M12.5 5.5l-7 7", stroke, "stroke-width": 1.8 });
    if (status === LOCKED_OUT) add("path", { d: "M3 15L15 3", stroke, "stroke-width": 1.5 });
    return svg;
  }

  function tagFor(q) {
    if (q.errand) return "ERRAND";
    if (q.activity) return "ACTIVITY";
    if (q.type === "faction") return FACTION_TAGS[q.faction] || "FACTION";
    if (q.type === "main") return "MAIN";
    return q.type.toUpperCase();
  }

  // Completion ring with the percentage inside, as in the starmap concept.
  function progressRing(fraction, color, cls) {
    const size = 52, r = 22, c = 2 * Math.PI * r;
    const svg = document.createElementNS(SVG, "svg");
    svg.setAttribute("class", cls || "ring");
    svg.setAttribute("viewBox", "0 0 " + size + " " + size);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", Math.round(fraction * 100) + "% complete");
    const circle = (attrs) => {
      const node = document.createElementNS(SVG, "circle");
      for (const [k, v] of Object.entries({ cx: size / 2, cy: size / 2, r, fill: "none", "stroke-width": 3, ...attrs })) node.setAttribute(k, v);
      svg.append(node);
    };
    circle({ stroke: "#26303a" });
    circle({ stroke: color, "stroke-dasharray": (fraction * c).toFixed(1) + " " + c.toFixed(1), transform: "rotate(-90 " + size / 2 + " " + size / 2 + ")" });
    const text = document.createElementNS(SVG, "text");
    for (const [k, v] of Object.entries({ x: size / 2, y: size / 2, "text-anchor": "middle", "dominant-baseline": "central", class: "ring-text" })) text.setAttribute(k, v);
    text.textContent = Math.round(fraction * 100) + "%";
    svg.append(text);
    return svg;
  }

  function renderHeader() {
    const tabs = document.getElementById("tabs");
    tabs.replaceChildren(...TABS.map((t) => el("button", { "aria-current": view.tab === t.id ? "page" : null, text: t.label, onclick: () => setTab(t.id) })));
    const quests = tally(DATA.quests.filter((q) => !q.activity));
    const activities = tally(DATA.quests.filter((q) => q.activity));
    const total = (t, label, color) => el("div", { class: "total" },
      progressRing(t.total ? t.done / t.total : 0, color),
      el("div", {},
        el("div", { class: "total-value" }, String(t.done), el("span", { text: " / " + t.total })),
        el("div", { class: "total-label", text: label })));
    document.getElementById("totals").replaceChildren(total(quests, "QUESTS", "#e9edf1"), total(activities, "ACTIVITIES", "#f0c43a"));
  }

  // header: optional block above the list (the Here tab's place summary).
  function renderSide(rows, header) {
    const side = document.getElementById("side");
    side.hidden = false;
    side.setAttribute("aria-label", TABS.find((t) => t.id === view.tab).label);
    side.replaceChildren(header || "", ...rows.map((row) => {
      if (row.kind === "group") return el("div", { class: "group" }, el("span", { text: row.label }), el("span", { text: row.frac || "" }));
      if (row.kind === "subgroup") return el("div", { class: "subgroup", text: row.label });
      const selected = view.selected[view.tab] === row.key;
      const cls = "item" + (row.count ? " count" : "") + (row.count && row.sub ? " sub" : "") + (selected ? " selected" : "") + (selected && view.focus === "list" ? " inactive" : "");
      const attrs = { class: cls, "aria-pressed": selected ? "true" : "false", onclick: () => select(row.key) };
      // Log categories show how many quests they hold; everything else shows progress.
      if (row.count) return el("button", attrs, el("span", { class: "item-head" }, el("span", { class: "item-name", text: row.label }), el("span", { class: "item-frac", text: String(row.quests.length) })));
      const t = tally(row.quests);
      const pct = t.total ? Math.round((t.done / t.total) * 100) : 0;
      return el("button", attrs,
        el("span", { class: "item-head" }, el("span", { class: "item-name", text: row.label }), el("span", { class: "item-frac", text: t.done + " / " + t.total })),
        el("span", { class: "track" }, el("span", { class: "fill", style: "width: " + pct + "%" })));
    }));
    const current = side.querySelector(".item.selected");
    if (current) current.scrollIntoView({ block: "nearest" });
  }

  // options.listTitle: compact layout (Here, Log) with only a title line above the list; the
  // summary lives in the side column. options.noFilters: list everything given (Log).
  function renderDetail(kicker, title, quests, options) {
    options = options || {};
    const t = tally(quests);
    const filtered = quests.filter((q) => available(q) && (options.noFilters || FILTERS.find((f) => f.id === view.filter).test(statusOf(q))));
    // Three groups: in progress, not discovered yet, then finished (completed, failed or
    // locked out: nothing left to do).
    const groups = [
      { label: "IN PROGRESS", quests: sortQuests(filtered.filter((q) => statusOf(q) === IN_PROGRESS)) },
      { label: "NOT DISCOVERED", quests: sortQuests(filtered.filter((q) => statusOf(q) === NOT_STARTED)) },
      { label: "FINISHED", quests: sortQuests(filtered.filter((q) => isFinished(statusOf(q)))) },
    ].filter((g) => g.quests.length);
    const shown = groups.flatMap((g) => g.quests);
    // Group headers only when the list mixes groups.
    const groupStarts = new Map();
    if (groups.length > 1) {
      let at = 0;
      for (const g of groups) { groupStarts.set(at, g); at += g.quests.length; }
    }
    const counts = { all: t.total, missing: t.missing, active: t.active, done: t.done };
    const filters = options.noFilters ? null : el("div", { class: "filters", role: "tablist", "aria-label": "Filter" },
      FILTERS.map((f) => el("button", { role: "tab", "aria-selected": view.filter === f.id ? "true" : "false", text: f.label + " " + counts[f.id], onclick: () => setFilter(f.id) })));
    const sort = el("button", { class: "sort", onclick: cycleSort }, el("span", { text: "SORT " }), SORTS.find((s) => s.id === view.sort).label);
    const controls = el("div", { class: "list-controls" }, filters, sort);
    const children = [];

    if (options.listTitle) {
      children.push(el("div", { class: "list-head" },
        el("div", { class: "list-title" }, options.listTitle, el("span", { text: " · " + shown.length })),
        controls));
    } else {
      renderSummary(children, kicker, title, quests, t, options);
      children.push(controls);
    }

    shownQuests = shown;
    view.row = Math.min(view.row, Math.max(0, shown.length - 1));
    const list = el("div", { class: "list" });
    if (shown.length === 0) list.append(el("div", { class: "empty", text: options.empty || "Nothing here for this filter." }));
    shown.forEach((q, index) => {
      const group = groupStarts.get(index);
      if (group) list.append(el("div", { class: "list-divider", text: group.label + " · " + group.quests.length }));
      const s = statusOf(q);
      const hide = view.spoilers && s === NOT_STARTED;
      const selected = view.focus === "list" && index === view.row;
      list.append(el("div", { class: "row" + (selected ? " selected" : "") + (isFinished(s) ? " finished" : "") + (notYetAvailable(q) ? " unavailable" : ""), onclick: () => selectRow(index), ondblclick: () => { selectRow(index); activate(); } },
        statusIcon(s, selected),
        el("span", { class: "row-name" + (hide ? " hidden" : "") },
          hide ? "Undiscovered " + (TYPE_NOUNS[q.activity ? "activity" : q.type] || "mission") : q.name,
          tracked.has(q.id) ? el("span", { class: "tracked-badge", text: "TRACKED" }) : null),
        el("span", { class: "row-tag", text: tagFor(q) }),
        el("span", { class: "row-meta", text: hide ? "" : rowMeta(q, s, options) })));
    });
    children.push(list);
    document.getElementById("detail").replaceChildren(...children.filter(Boolean));
    const current = document.querySelector(".row.selected");
    if (current) current.scrollIntoView({ block: "nearest" });
  }

  // Order within each group (found / not discovered). Default keeps the data's order: story
  // order for questlines, quest-giver order for places.
  const STATUS_ORDER = { [IN_PROGRESS]: 0, [COMPLETED]: 1, [LOCKED_OUT]: 2, [FAILED]: 3, [NOT_STARTED]: 4 };
  const placePath = (q) => placeChain(q.place).reverse().map((p) => p.name).join(" / ");
  function sortQuests(list) {
    if (view.sort === "default") return list;
    const byName = (a, b) => a.name.localeCompare(b.name);
    const compare = {
      name: byName,
      status: (a, b) => STATUS_ORDER[statusOf(a)] - STATUS_ORDER[statusOf(b)] || byName(a, b),
      place: (a, b) => placePath(a).localeCompare(placePath(b)) || byName(a, b),
      type: (a, b) => tagFor(a).localeCompare(tagFor(b)) || byName(a, b),
    }[view.sort];
    return [...list].sort(compare);
  }

  // Title, progress bar (or questline chain) and counts above the list (Locations, Quests, Activities).
  function renderSummary(children, kicker, title, quests, t, options) {
    children.push(el("div", {}, el("div", { class: "kicker", text: kicker }), el("h1", { class: "title", text: title })));

    if (options.chain) {
      const chain = el("div", { class: "chain", role: "img", "aria-label": t.done + " of " + t.total + " completed" });
      quests.filter(available).forEach((q, i) => {
        const s = statusOf(q);
        if (i > 0) chain.append(el("b", { class: isDone(s) || s === IN_PROGRESS ? "done" : "" }));
        chain.append(el("i", { class: isDone(s) ? "done" : s === IN_PROGRESS ? "active" : "" }));
      });
      children.push(chain);
    } else {
      const bar = el("div", { class: "segments", role: "img", "aria-label": t.done + " of " + t.total + " completed" });
      const cells = Math.min(t.total, 60);
      for (let i = 0; i < cells; i++) {
        const at = ((i + 0.5) / cells) * t.total;
        bar.append(el("i", { class: at < t.done ? "done" : at < t.done + t.active ? "active" : at < t.done + t.active + t.failed ? "failed" : "" }));
      }
      children.push(bar);
    }

    const stat = (value, label, cls) => el("div", {}, el("div", { class: "stat-value " + (cls || ""), text: String(value) }), el("div", { class: "stat-label", text: label }));
    children.push(el("div", { class: "stats" },
      stat(t.done, "COMPLETED"), stat(t.active, "IN PROGRESS", "active"), stat(t.missing, "NOT STARTED"),
      t.failed ? stat(t.failed, "FAILED", "failed") : null));
    if (options.note) children.push(el("div", { class: "note", text: options.note }));
  }

  // Here tab's side column: where the player is, how much is done there.
  function hereSummary(kicker, title, badges, quests) {
    const t = tally(quests);
    const count = (value, label, cls) => [el("b", { class: cls || "", text: String(value) }), el("span", { text: label })];
    return el("div", { class: "here-summary" },
      el("div", {}, el("div", { class: "kicker", text: kicker }), el("h1", { class: "here-title", text: title })),
      badges.length ? el("div", { class: "badges" }, badges.map((b) => el("span", { text: b }))) : null,
      el("div", { class: "here-stats" },
        progressRing(t.total ? t.done / t.total : 0, "#e9edf1", "ring big"),
        el("div", { class: "here-counts" },
          count(t.done, "COMPLETED"), count(t.active, "IN PROGRESS", "active"), count(t.missing, "NOT STARTED"),
          t.failed ? count(t.failed, "FAILED", "failed") : null)));
  }

  // ------------------------------------------------------------------ actions (handled by Completionist:MenuBridge)

  const hasStartLocation = (q) => placeChain(q.place).some((p) => p.loc);

  // "Track" sets a started quest as the active mission; "Show on map" plots a course to where it starts.
  function actionsFor(q) {
    const s = statusOf(q);
    const actions = [];
    if (s === IN_PROGRESS) {
      actions.push(tracked.has(q.id)
        ? { id: "untrack", label: "UNTRACK", run: () => send("untrack", q) }
        : { id: "track", label: "TRACK", run: () => send("track", q) });
    }
    if (!isDone(s) && hasStartLocation(q)) actions.push({ id: "plot", label: "SHOW ON MAP", run: () => send("plot", q) });
    actions.push(overrideAction(q));
    return actions;
  }

  // Manual override for when detection gets a quest wrong; saved in the game save by the tracker.
  // Never the default (Enter / A) action, so nothing gets marked by accident.
  function overrideAction(q) {
    if (manual.has(q.id)) return { id: "override", label: "RESET TO AUTO", run: () => setOverride(q, 0) };
    if (isDone(statusOf(q))) return { id: "override", label: "MARK NOT DONE", run: () => setOverride(q, 2) };
    return { id: "override", label: "MARK DONE", run: () => setOverride(q, 1) };
  }

  function setOverride(q, value) {
    if (bridge) {
      bridge.send("override", q.id, value);
      return;
    }
    if (!demoAuto.has(q.id)) demoAuto.set(q.id, statusOf(q));
    if (value === 0) {
      statuses.set(q.id, demoAuto.get(q.id));
      manual.delete(q.id);
    } else {
      statuses.set(q.id, value === 1 ? COMPLETED : NOT_STARTED);
      manual.add(q.id);
    }
    render();
  }

  const primaryAction = (q) => actionsFor(q).find((a) => a.id !== "override");


  function send(action, q) {
    if (bridge) bridge.send(action, q.id);
    else {
      console.log("[preview] " + action + " " + q.id);
      if (action === "track") { tracked.add(q.id); showToast("Now tracking: " + q.name); render(); }
      if (action === "untrack") { tracked.delete(q.id); showToast("Stopped tracking: " + q.name); render(); }
    }
  }

  function selectedQuest() {
    return view.focus === "list" ? shownQuests[view.row] : undefined;
  }

  function lockedReason(q) {
    for (const choice of q.choices || []) {
      const otherSideDone = DATA.quests.some((other) =>
        other !== q && (other.choices || []).some((c) => c.group === choice.group && c.side !== choice.side) && statusOf(other) === COMPLETED);
      if (otherSideDone) return (DATA.choiceLabels[choice.group] || {})[choice.side] || "Other path chosen";
    }
    return "Other path chosen";
  }

  function rowMeta(q, s, options) {
    if (notYetAvailable(q)) return "Available in New Game+";
    if (manual.has(q.id)) return "Marked manually";
    if (s === LOCKED_OUT) return lockedReason(q);
    return options.meta ? options.meta(q) : q.giver || "";
  }

  function hubName(q) {
    const chain = placeChain(q.place);
    return chain.length ? chain[0].name : "Anywhere";
  }

  function render() {
    if (!loaded) {
      document.getElementById("side").hidden = true;
      document.getElementById("detail").replaceChildren(el("div", { class: "kicker", text: "LOADING PROGRESS…" }));
      return;
    }
    renderBody();
    renderKeys();
  }

  function renderBody() {
    renderHeader();
    shownCards = [];
    const rows = sideRows();
    const items = rows.filter((r) => r.kind === "item");
    if (!items.some((r) => r.key === view.selected[view.tab]) && items.length) view.selected[view.tab] = items[0].key;

    if (view.tab === "here") {
      renderHere(rows);
      return;
    }
    renderSide(rows);
    if (view.tab === "log") {
      const row = items.find((r) => r.key === view.selected.log);
      renderDetail("", "", row ? row.quests : [], { listTitle: row ? row.label.toUpperCase() : "", noFilters: true, meta: hubName, empty: "Nothing here yet." });
    } else if (view.tab === "questlines") {
      const row = rows.find((r) => r.key === view.selected.questlines);
      if (row) renderDetail((row.sub || "").toUpperCase(), row.label, row.quests, { chain: true, meta: hubName });
    } else {
      const row = rows.find((r) => r.kind === "item" && r.key === view.selected[view.tab]);
      if (!row) return renderDetail("", "Nothing tracked", [], {});
      const chain = row.key === "all" || row.key === "anywhere" ? [] : placeChain(row.key);
      const kicker = chain.slice(1).map((p) => p.name.toUpperCase() + (p.kind === "system" ? " SYSTEM" : "")).join(" · ");
      const options = view.tab === "activities" && row.key === "all" ? { meta: hubName } : {};
      // The game's stat (and the Fixer achievement) also counts small errands and repeatable activities.
      if (view.tab === "activities" && gameActivities !== null) {
        options.note = "Game count: " + gameActivities + " activities completed, including small errands and repeatable activities this list leaves out.";
      }
      renderDetail(kicker, row.label, row.quests, options);
    }
  }

  // ------------------------------------------------------------------ Here tab

  const placeName = (key) => (DATA.places[key] ? DATA.places[key].name : "");

  // Here: the side column sums up where the player is (and, on a planet or in a system, lists
  // the places in it); the rest is the quest list. Anywhere without tracked quests suggests
  // where to go next.
  function renderHere(rows) {
    const key = herePlace();
    if (!key) {
      document.getElementById("side").hidden = true;
      return renderNowhere();
    }
    const place = DATA.places[key];
    const chain = placeChain(key);
    const systemName = (chain.find((p) => p.kind === "system") || {}).name || "";
    let kicker, badges = [], meta;

    if (place.kind === "planet") {
      kicker = systemName.toUpperCase() + " SYSTEM · " + (inSpace ? "IN ORBIT" : "ON THE SURFACE");
      badges = ["PLANET", survey >= 0 ? "SURVEYED " + Math.round(survey * 100) + "%" : null].filter(Boolean);
      meta = hubName;
    } else if (place.kind === "system") {
      kicker = inSpace ? "IN SPACE" : "STAR SYSTEM";
      badges = ["STAR SYSTEM"];
      meta = (q) => {
        const c = placeChain(q.place);
        const planet = c.find((p) => p.kind === "planet");
        return planet && planet !== c[0] ? c[0].name + " · " + planet.name : c.length ? c[0].name : "";
      };
    } else {
      kicker = chain.slice(1).map((p) => p.name.toUpperCase() + (p.kind === "system" ? " SYSTEM" : "")).join(" · ");
    }
    const items = rows.filter((r) => r.kind === "item");
    hereLayout = items.length ? "places" : "city";
    if (view.focus === "cards" || (view.focus === "side" && !items.length)) view.focus = "list";

    const all = questsUnder(key);
    renderSide(rows, hereSummary(kicker, place.name, badges, all));
    const row = items.find((r) => r.key === view.selected.here);
    renderDetail("", "", row ? row.quests : all, { listTitle: (row ? row.label : place.name).toUpperCase(), meta });
  }

  // Cards for the places under a planet (by hub) or a system (by planet), with progress.
  function placeCards(key, level) {
    const groups = new Map();
    for (const q of questsUnder(key)) {
      if (!available(q) || notYetAvailable(q)) continue;
      const chain = placeChain(q.place);
      const holder = level === "hub" ? chain[0] : chain.find((p) => p.kind === "planet") || chain[0];
      const groupKey = holder ? holder.key : key;
      if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, quests: [], hubs: new Set() });
      const g = groups.get(groupKey);
      g.quests.push(q);
      if (chain[0] && chain[0].key !== groupKey) g.hubs.add(chain[0].name);
    }
    return [...groups.values()]
      .sort((a, b) => b.quests.length - a.quests.length)
      .map((g) => {
        const hubs = [...g.hubs];
        const isSelf = g.key === key;
        return {
          key: g.key,
          label: isSelf ? (level === "hub" ? "Elsewhere on " + placeName(key) : "In space") : placeName(g.key),
          sub: level === "planet" && hubs.length ? hubs[0] + (hubs.length > 1 ? " · " + (hubs.length - 1) + " more" : "") : null,
          quests: g.quests,
          openKey: placeChain(g.quests[0].place)[0].key,
          loc: (DATA.places[g.key] || {}).loc,
        };
      });
  }

  // Nothing tracked here: systems with the most quests not started, and quests to track.
  function renderNowhere() {
    // Start in the left list (where to go next) when arriving at this page.
    if (hereLayout !== "nowhere" || (view.focus !== "cards" && view.focus !== "list")) view.focus = "cards";
    hereLayout = "nowhere";
    let systemName = "";
    for (const id of locationChain) {
      const hit = Object.entries(DATA.systems || {}).find(([loc]) => matchesLocation(id, loc));
      if (hit) { systemName = hit[1]; break; }
    }

    const bySystem = new Map();
    for (const q of DATA.quests) {
      if (!available(q) || notYetAvailable(q)) continue;
      const system = placeChain(q.place).find((p) => p.kind === "system");
      if (!system) continue;
      if (!bySystem.has(system.key)) bySystem.set(system.key, { key: system.key, quests: [] });
      bySystem.get(system.key).quests.push(q);
    }
    shownCards = [...bySystem.values()]
      .map((s) => ({ ...s, label: placeName(s.key), loc: (DATA.places[s.key] || {}).loc, t: tally(s.quests) }))
      .filter((s) => s.t.missing > 0)
      .sort((a, b) => b.t.missing - a.t.missing)
      .slice(0, 6);
    shownQuests = DATA.quests.filter((q) => available(q) && statusOf(q) === IN_PROGRESS);
    view.card = Math.min(view.card, Math.max(0, shownCards.length - 1));
    view.row = Math.min(view.row, Math.max(0, shownQuests.length - 1));

    const systemRows = shownCards.map((s, index) => {
      const selected = view.focus === "cards" && index === view.card;
      return el("div", { class: "next-row" + (selected ? " selected" : ""), onclick: () => { view.focus = "cards"; view.card = index; render(); }, ondblclick: () => openCard(index) },
        el("div", { class: "next-main" },
          el("span", { class: "item-head" }, el("span", { class: "item-name", text: s.label }), el("span", { class: "item-frac", text: s.t.missing + " not started" })),
          el("span", { class: "track" }, el("span", { class: "fill", style: "width: " + (s.t.total ? Math.round((s.t.done / s.t.total) * 100) : 0) + "%" }))));
    });
    const activeRows = shownQuests.map((q, index) => {
      const selected = view.focus === "list" && index === view.row;
      return el("div", { class: "row" + (selected ? " selected" : ""), onclick: () => selectRow(index), ondblclick: () => { selectRow(index); activate(); } },
        statusIcon(IN_PROGRESS, selected),
        el("span", { class: "row-name" }, q.name, tracked.has(q.id) ? el("span", { class: "tracked-badge", text: "TRACKED" }) : null),
        el("span", { class: "row-meta", text: hubName(q) }));
    });

    document.getElementById("detail").replaceChildren(
      el("div", {},
        el("div", { class: "kicker", text: [inSpace ? "IN SPACE" : "", systemName ? systemName.toUpperCase() + " SYSTEM" : ""].filter(Boolean).join(" · ") }),
        el("h1", { class: "title", text: "Nothing tracked here" }),
        el("p", { class: "lead", text: "No quests or activities start here. Here's where you can pick up more." })),
      el("div", { class: "nowhere" },
        el("div", { class: "nowhere-col" }, el("div", { class: "section-title ruled", text: "WHERE TO NEXT · MOST NOT STARTED" }), el("div", { class: "nowhere-list" }, systemRows)),
        el("div", { class: "nowhere-col narrow" }, el("div", { class: "section-title ruled", text: "IN PROGRESS · PICK ONE TO TRACK" }),
          el("div", { class: "nowhere-list" }, activeRows.length ? activeRows : el("div", { class: "empty", text: "No quests in progress." })))));
    const current = document.querySelector(".next-row.selected, .row.selected");
    if (current) current.scrollIntoView({ block: "nearest" });
  }

  // Short message above the footer, e.g. the result of Track.
  let toastTimer = 0;
  function showToast(text) {
    let toast = document.getElementById("toast");
    if (!toast) {
      toast = el("div", { id: "toast", class: "toast", role: "status" });
      document.querySelector(".app").append(toast);
    }
    toast.textContent = text;
    toast.classList.add("visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove("visible"), 3500);
  }

  function plotLocation(locKey) {
    const [plugin, hex] = locKey.split("|");
    if (bridge) bridge.send("plotLocation", parseInt(hex, 16), plugin);
    else console.log("[preview] plotLocation " + locKey);
  }

  // Systems on the nothing-tracked page: set course there.
  function openCard(index) {
    const card = shownCards[index];
    if (card && card.loc) plotLocation(card.loc);
  }

  // The place / questline / category selected in the side column, while it has focus.
  function selectedSideItem() {
    if (view.focus !== "side") return null;
    return sideRows().find((r) => r.kind === "item" && r.key === view.selected[view.tab]) || null;
  }
  const sideItemLocation = (item) => item && (item.loc || (DATA.places[item.key] || {}).loc);

  // Footer prompts follow the last input device, like the game's own menus.
  function renderKeys() {
    const pad = view.input === "gamepad";
    const key = (k, label, end, run) => el("button", { class: end ? "end" : "", onclick: run }, el("kbd", { text: k }), label);
    const q = selectedQuest();
    const onCard = view.focus === "cards" && shownCards.length > 0;
    const sideLoc = sideItemLocation(selectedSideItem());
    const primary = view.focus === "side" ? "OPEN" : onCard ? "SET COURSE" : q ? (primaryAction(q) || {}).label : null;
    const canPlot = view.focus === "side" ? !!sideLoc : !onCard && q && actionsFor(q).some((a) => a.id === "plot");
    const checklist = view.tab !== "log"; // the Log only lists found quests: no filter, nothing to hide
    const keys = [
      key(pad ? "LB / RB" : "Q / E", "SWITCH TAB", false, () => cycleTab(1)),
      primary ? key(pad ? "A" : "ENTER", primary, false, activate) : null,
      canPlot ? key(pad ? "X" : "R", view.focus === "side" ? "SET COURSE" : "SHOW ON MAP", false, plotSelected) : null,
      q ? key(pad ? "RS" : "M", overrideAction(q).label, false, overrideSelected) : null,
      checklist ? key(pad ? "Y" : "F", "FILTER", false, cycleFilter) : null,
      view.tab !== "here" || hereLayout !== "nowhere" ? key(pad ? "LS" : "T", "SORT: " + SORTS.find((s) => s.id === view.sort).label, false, cycleSort) : null,
      checklist ? key(pad ? "VIEW" : "X", "SPOILERS: " + (view.spoilers ? "HIDDEN" : "SHOWN"), false, toggleSpoilers) : null,
      key(pad ? "B" : "ESC", "CLOSE", true, () => { if (bridge) bridge.send("close"); }),
    ];
    document.getElementById("keys").replaceChildren(...keys.filter(Boolean));
  }

  // ------------------------------------------------------------------ input

  function setTab(id) {
    view.tab = id;
    view.focus = id === "here" || id === "log" ? "list" : "side";
    view.row = 0;
    view.card = 0;
    render();
  }
  function select(key) {
    view.selected[view.tab] = key;
    view.focus = "side";
    view.row = 0;
    render();
  }
  function selectRow(index) {
    view.focus = "list";
    view.row = index;
    render();
  }
  function setFilter(id) {
    view.filter = id;
    view.row = 0;
    render();
  }
  function cycleTab(delta) {
    const i = TABS.findIndex((t) => t.id === view.tab);
    setTab(TABS[(i + TABS.length + delta) % TABS.length].id);
  }
  function cycleFilter() {
    if (view.tab === "log") return;
    const i = FILTERS.findIndex((f) => f.id === view.filter);
    setFilter(FILTERS[(i + 1) % FILTERS.length].id);
  }
  function cycleSort() {
    const i = SORTS.findIndex((s) => s.id === view.sort);
    view.sort = SORTS[(i + 1) % SORTS.length].id;
    writeSetting("sort", view.sort);
    view.row = 0;
    render();
  }
  function toggleSpoilers() {
    if (view.tab === "log") return;
    view.spoilers = !view.spoilers;
    writeSetting("spoilers", view.spoilers);
    render();
  }

  // Up/down moves within the focused column; left/right moves between the columns.
  function move(delta) {
    if (view.focus === "cards") {
      view.card = Math.min(shownCards.length - 1, Math.max(0, view.card + delta));
      return render();
    }
    if (view.focus === "list") {
      if (shownQuests.length) selectRow(Math.min(shownQuests.length - 1, Math.max(0, view.row + delta)));
      return;
    }
    const items = sideRows().filter((r) => r.kind === "item");
    if (!items.length) return;
    const at = Math.max(0, items.findIndex((r) => r.key === view.selected[view.tab]));
    select(items[Math.min(items.length - 1, Math.max(0, at + delta))].key);
  }
  function focusColumn(column) {
    if (view.tab === "here" && hereLayout === "nowhere") {
      // Left: the systems list; right: quests in progress.
      const target = column === "side" ? "cards" : "list";
      if (target === "list" && !shownQuests.length) return;
      view.focus = target;
      return render();
    }
    if (column === "list" && !shownQuests.length) return;
    if (column === "side" && !sideRows().some((r) => r.kind === "item")) return;
    view.focus = column;
    render();
  }

  // Enter / A: open the selected place, or run the selected quest's main action.
  function activate() {
    if (view.focus === "cards") return openCard(view.card);
    if (view.focus === "side") return focusColumn("list");
    const q = selectedQuest();
    const action = q && primaryAction(q);
    if (action) action.run();
  }
  function overrideSelected() {
    const q = selectedQuest();
    if (q) overrideAction(q).run();
  }
  function plotSelected() {
    if (view.focus === "cards") {
      const card = shownCards[view.card];
      if (card && card.loc) plotLocation(card.loc);
      return;
    }
    if (view.focus === "side") {
      const loc = sideItemLocation(selectedSideItem());
      if (loc) plotLocation(loc);
      return;
    }
    const q = selectedQuest();
    const action = q && actionsFor(q).find((a) => a.id === "plot");
    if (action) action.run();
  }

  // Controller: OSF UI turns the D-pad / left stick into arrow keys and A into Enter, and B closes
  // the menu. Every button also arrives as a "ui.gamepad" event (XInput button masks), which is
  // how the shoulder buttons, X, Y and View work here.
  const PAD = { VIEW: 0x0020, LS: 0x0040, RS: 0x0080, LB: 0x0100, RB: 0x0200, A: 0x1000, X: 0x4000, Y: 0x8000 };
  if (bridge) {
    bridge.on("ui.gamepad", (event) => {
      if (!event || event.kind !== "button" || !event.button || !event.button.down) return;
      if (view.input !== "gamepad") {
        view.input = "gamepad";
        renderKeys();
      }
      const id = event.button.id;
      if (id === PAD.LB) cycleTab(-1);
      else if (id === PAD.RB) cycleTab(1);
      else if (id === PAD.X) plotSelected();
      else if (id === PAD.Y) cycleFilter();
      else if (id === PAD.VIEW) toggleSpoilers();
      else if (id === PAD.RS) overrideSelected();
      else if (id === PAD.LS) cycleSort();
    });
  }
  document.addEventListener("mousemove", () => {
    if (view.input !== "keyboard") {
      view.input = "keyboard";
      renderKeys();
    }
  });

  document.addEventListener("keydown", (event) => {
    const key = event.key.toLowerCase();
    // Arrow keys and Enter also come from the controller, so only other keys switch the prompts back.
    if (!["arrowup", "arrowdown", "arrowleft", "arrowright", "enter"].includes(key) && view.input !== "keyboard") {
      view.input = "keyboard";
    }
    if (key === "escape" || key === "tab") {
      event.preventDefault();
      if (bridge) bridge.send("close");
    } else if (key === "q") {
      cycleTab(-1);
    } else if (key === "e") {
      cycleTab(1);
    } else if (key === "arrowup" || key === "w") {
      event.preventDefault();
      move(-1);
    } else if (key === "arrowdown" || key === "s") {
      event.preventDefault();
      move(1);
    } else if (key === "arrowleft" || key === "a") {
      event.preventDefault();
      focusColumn("side");
    } else if (key === "arrowright" || key === "d") {
      event.preventDefault();
      focusColumn("list");
    } else if (key === "enter") {
      event.preventDefault();
      activate();
    } else if (key === "m") {
      overrideSelected();
    } else if (key === "r") {
      plotSelected();
    } else if (key === "f") {
      cycleFilter();
    } else if (key === "t") {
      cycleSort();
    } else if (key === "x") {
      toggleSpoilers();
    }
  });

  // Redraw whenever the menu is shown or focused, so reopening it never shows stale content.
  document.addEventListener("visibilitychange", () => { if (!document.hidden) render(); });
  window.addEventListener("focus", render);

  render();
})();
